package vn.edu.ptit.english.service.impl;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import vn.edu.ptit.english.dto.AuthoringData.*;
import vn.edu.ptit.english.dto.AuthoringRequests.*;
import vn.edu.ptit.english.dto.AuthoringRequests;
import vn.edu.ptit.english.dto.CatalogViews.*;
import vn.edu.ptit.english.dto.MaterialRequests.Command;
import vn.edu.ptit.english.entity.*;
import vn.edu.ptit.english.enums.Role;
import vn.edu.ptit.english.exception.ApiException;
import vn.edu.ptit.english.repository.*;
import vn.edu.ptit.english.repository.ContentRepository.Filter;
import vn.edu.ptit.english.security.*;
import vn.edu.ptit.english.service.*;
import vn.edu.ptit.english.service.RequestReceiptService.Result;
import static vn.edu.ptit.english.service.impl.AuthoringAccess.*;
import static vn.edu.ptit.english.dto.MaterialRequests.invalid;

@Service @Transactional(readOnly=true,isolation=Isolation.READ_COMMITTED)
public class AuthoringServiceImpl implements AuthoringService {
    private final ContentRepository content;private final CatalogRepository catalog;private final RequestReceiptService receipts;private final AccountGuard accounts;private final AuthoringPublication publication;private final ContentGovernance governance;
    public AuthoringServiceImpl(ContentRepository content,CatalogRepository catalog,RequestReceiptService receipts,AccountGuard accounts,AuthoringPublication publication,ContentGovernance governance){this.governance=governance;this.content=content;this.catalog=catalog;this.receipts=receipts;this.accounts=accounts;this.publication=publication;}
    private boolean own(CatalogEntity root,UserPrincipal actor){return governance.manages(root,actor);}
    private void editable(CatalogEntity root,UserPrincipal actor){governance.editable(root,actor);}
    private void author(UserPrincipal actor){accounts.requireCurrent(actor);AssetServiceImpl.author(actor);}
    private QuestionEntity question(long id,boolean lock){return content.question(AuthoringRequests.id(id),lock).orElseThrow(AuthoringAccess::missing);}
    private LessonEntity lesson(long id,boolean lock){return content.lesson(AuthoringRequests.id(id),lock).orElseThrow(AuthoringAccess::missing);}
    private void readable(CatalogEntity root,boolean active,UserPrincipal actor){if(!own(root,actor)&&!active)throw missing();}
    private Map<String,Object> view(QuestionEntity root,UserPrincipal actor,boolean summary,boolean publishedScope){var draft=own(root,actor)?root.getDraft():null;var pub=root.getPublished();var result=AuthoringAccess.root(root,root.status(),draft==null?null:draft.getId(),pub==null?null:pub.getId());result.put("originKey",root.getOriginKey());if(summary){var selected=!publishedScope&&draft!=null?draft:pub;var d=selected.data();result.put("type",d.type());result.put("topicId",d.topicId());result.put("objectiveId",d.objectiveId());result.put("difficulty",d.difficulty());result.put("promptExcerpt",d.prompt().substring(0,Math.min(200,d.prompt().length())));}else{result.put("draft",draft==null?null:draft.view());result.put("published",pub==null?null:pub.view());}result.put("canEdit",own(root,actor));result.put("review",own(root,actor)?governance.reviewView("questions",root.getId(),draft!=null?draft.getId():pub!=null?pub.getId():null):null);return result;}
    private Map<String,Object> view(LessonEntity root,UserPrincipal actor,boolean summary,boolean publishedScope){var draft=own(root,actor)?root.getDraft():null;var pub=root.getPublished();var result=AuthoringAccess.root(root,root.status(),draft==null?null:draft.getId(),pub==null?null:pub.getId());result.put("unitId",root.getUnitId());result.put("sortOrder",root.getSortOrder());if(summary){var selected=!publishedScope&&draft!=null?draft:pub;result.put("title",selected==null?"Bài đã bỏ nháp":selected.data().title());}else{result.put("draft",draft==null?null:draft.view());result.put("published",pub==null?null:pub.view());}result.put("canEdit",own(root,actor));result.put("review",own(root,actor)?governance.reviewView("lessons",root.getId(),draft!=null?draft.getId():pub!=null?pub.getId():null):null);return result;}
    private <V extends AuthoredVersion> V draft(V draft,Long expected){if(draft==null||(expected!=null&&!draft.getId().equals(expected)))throw conflict("DRAFT_MISMATCH","Bản nháp đã thay đổi hoặc không còn tồn tại.");return draft;}
    private void filter(Filter f,UserPrincipal actor){if(!Set.of("OWN","PUBLISHED","ALL").contains(f.scope())||f.q().length()>100||f.page()<0||f.size()<1||f.size()>50||f.status()!=null&&!Set.of("DRAFT","PUBLISHED","RETIRED").contains(f.status())||f.type()!=null&&!AuthoringRequests.TYPES.contains(f.type())||f.difficulty()!=null&&!AuthoringRequests.DIFFICULTIES.contains(f.difficulty()))throw invalid("query","Bộ lọc hoặc trang không hợp lệ.");if(f.scope().equals("ALL")&&actor.role()!=Role.ADMIN)throw new ApiException(HttpStatus.FORBIDDEN,"ACCESS_DENIED","Chỉ quản trị viên được xem mọi bản nháp.");if(f.topicId()!=null)AuthoringRequests.id(f.topicId());if(f.objectiveId()!=null)AuthoringRequests.id(f.objectiveId());if(f.unitId()!=null)AuthoringRequests.id(f.unitId());}
    public CatalogPage<Map<String,Object>> list(String kind,Filter f,UserPrincipal actor){author(actor);filter(f,actor);boolean pub=f.scope().equals("PUBLISHED");return kind.equals("questions")?CatalogPage.from(content.questions(f,actor.id(),actor.role()==Role.ADMIN).map(v->view(v,actor,true,pub))):CatalogPage.from(content.lessons(f,actor.id(),actor.role()==Role.ADMIN).map(v->view(v,actor,true,pub)));}
    public Map<String,Object> get(String kind,long id,UserPrincipal actor){author(actor);if(kind.equals("questions")){var q=question(id,false);readable(q,q.getPublished()!=null&&q.getRetiredAt()==null,actor);return view(q,actor,false,false);}var l=lesson(id,false);readable(l,l.getPublished()!=null&&l.getRetiredAt()==null,actor);return view(l,actor,false,false);}
    public Map<String,Object> version(String kind,long id,long version,UserPrincipal actor){get(kind,id,actor);AuthoringRequests.id(version);if(kind.equals("questions")){var v=content.questionVersion(version).orElseThrow(AuthoringAccess::missing);if(v.getQuestionId()!=id||!own(question(id,false),actor)&&!v.getState().equals("PUBLISHED"))throw missing();return v.view();}var v=content.lessonVersion(version).orElseThrow(AuthoringAccess::missing);if(v.getLessonId()!=id||!own(lesson(id,false),actor)&&!v.getState().equals("PUBLISHED"))throw missing();return v.view();}
    @Transactional(isolation=Isolation.READ_COMMITTED) public Result create(QuestionInput input,UserPrincipal actor){AssetServiceImpl.author(actor);return receipts.execute(actor,input.requestId(),"POST /api/author/questions",input.payload(),201,()->createQuestion(input.data(),UUID.randomUUID().toString(),actor));}
    private Map<String,Object> createQuestion(Question data,String origin,UserPrincipal actor){governance.lock();publication.validateQuestionReferences(data,actor);var root=content.save(new QuestionEntity(actor.id(),origin));var version=content.save(new QuestionVersionEntity(root.getId(),1,data));root.initialDraft(version);return view(content.save(root),actor,false,false);}
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Result create(LessonInput input,UserPrincipal actor){
        AssetServiceImpl.author(actor);
        return receipts.execute(actor,input.requestId(),"POST /api/author/lessons",input.payload(),201,()->{governance.lock();
            var unit=catalog.unit(input.unitId(),true).orElseThrow(AuthoringAccess::missing);
            content.refresh(unit);
            editable(unit,actor);
            revision(unit.getRevision(),input.unitBaseRevision());
            var existing=content.lessons(unit.getId());
            if(existing.size()>=100)throw invalid("unitId","Mỗi Unit tối đa 100 bài ở P0.");
            publication.validateLessonReferences(input.data(),unit.getId(),actor);
            int next=existing.stream().mapToInt(LessonEntity::getSortOrder).max().orElse(-1)+1;
            var root=content.save(new LessonEntity(actor.id(),unit.getId(),next));
            var version=content.save(new LessonVersionEntity(root.getId(),1,input.data()));
            root.initialDraft(version);
            unit.changed();
            catalog.save(unit);
            return view(content.save(root),actor,false,false);
        });
    }
    @Transactional(isolation=Isolation.READ_COMMITTED) public Result update(long id,QuestionInput input,UserPrincipal actor){AssetServiceImpl.author(actor);return receipts.execute(actor,input.requestId(),"PUT /api/author/questions/"+id+"/draft",input.payload(),200,()->{governance.lock();var root=question(id,true);editable(root,actor);governance.draftFree("questions",id);var v=draft(root.getDraft(),input.draftVersionId());content.refresh(v);revision(v.getRevision(),input.baseRevision());publication.validateQuestionReferences(input.data(),actor);if(v.update(input.data())){content.save(v);root.changed();content.save(root);}return view(root,actor,false,false);});}
    @Transactional(isolation=Isolation.READ_COMMITTED) public Result update(long id,LessonInput input,UserPrincipal actor){AssetServiceImpl.author(actor);return receipts.execute(actor,input.requestId(),"PUT /api/author/lessons/"+id+"/draft",input.payload(),200,()->{governance.lock();var root=lesson(id,true);editable(root,actor);governance.draftFree("lessons",id);var v=draft(root.getDraft(),input.draftVersionId());content.refresh(v);revision(v.getRevision(),input.baseRevision());publication.validateLessonReferences(input.data(),root.getUnitId(),actor);if(v.update(input.data())){content.save(v);root.changed();content.save(root);}return view(root,actor,false,false);});}
    @Transactional(isolation=Isolation.READ_COMMITTED) public Result start(String kind,long id,Command input,UserPrincipal actor){AssetServiceImpl.author(actor);return receipts.execute(actor,input.requestId(),"POST /api/author/"+kind+"/"+id+"/draft",input,200,()->{governance.lock();if(kind.equals("questions")){var root=question(id,true);editable(root,actor);governance.draftFree("questions",id);revision(root.getRevision(),input.baseRevision());if(root.getDraft()==null){if(root.getPublished()==null)throw conflict("DRAFT_MISMATCH","Câu hỏi đã bỏ nháp và chưa có bản công bố. Hãy tạo câu hỏi mới.");root.startDraft(content.save(new QuestionVersionEntity(id,root.getLastVersionNo()+1,root.getPublished().data())));content.save(root);}return view(root,actor,false,false);}var root=lesson(id,true);editable(root,actor);governance.draftFree("lessons",id);revision(root.getRevision(),input.baseRevision());if(root.getDraft()==null){if(root.getPublished()==null)throw conflict("DRAFT_MISMATCH","Bài học đã bỏ nháp và chưa có bản công bố. Hãy tạo bài mới.");root.startDraft(content.save(new LessonVersionEntity(id,root.getLastVersionNo()+1,root.getPublished().data())));content.save(root);}return view(root,actor,false,false);});}
    @Transactional(isolation=Isolation.READ_COMMITTED) public Result discard(String kind,long id,Command input,UserPrincipal actor){AssetServiceImpl.author(actor);return receipts.execute(actor,input.requestId(),"DELETE /api/author/"+kind+"/"+id+"/draft",input,204,()->{governance.lock();if(kind.equals("questions")){var root=question(id,true);editable(root,actor);governance.draftFree("questions",id);var v=draft(root.getDraft(),input.draftVersionId());content.refresh(v);revision(v.getRevision(),input.baseRevision());if(content.questionReferenced(v.getId()))throw conflict("CONTENT_IN_USE","Bản nháp câu hỏi đang được bài học tham chiếu.");root.discard();content.save(root);content.delete(v);}else{var root=lesson(id,true);editable(root,actor);governance.draftFree("lessons",id);var v=draft(root.getDraft(),input.draftVersionId());content.refresh(v);revision(v.getRevision(),input.baseRevision());root.discard();content.save(root);content.delete(v);}return null;});}
    public Preview preview(String kind,long id,UserPrincipal actor){author(actor);AuthoringRequests.id(id);return publication.preview(kind,id,actor);}
    @Transactional(isolation=Isolation.READ_COMMITTED) public Result publish(String kind,long id,Command input,UserPrincipal actor){AssetServiceImpl.author(actor);return receipts.execute(actor,input.requestId(),"POST /api/author/"+kind+"/"+id+"/publish",input,200,()->{governance.lock();ContentGovernance.admin(actor);governance.draftFree(kind,id);publication.publish(kind,AuthoringRequests.id(id),input,actor);return get(kind,id,actor);});}
    @Transactional(isolation=Isolation.READ_COMMITTED) public Result retire(String kind,long id,Command input,UserPrincipal actor){AssetServiceImpl.author(actor);return receipts.execute(actor,input.requestId(),"POST /api/author/"+kind+"/"+id+"/retire",input,200,()->{governance.lock();ContentGovernance.admin(actor);if(kind.equals("questions")){var root=question(id,true);editable(root,actor);governance.draftFree("questions",id);revision(root.getRevision(),input.baseRevision());if(content.questionInUse(id))throw conflict("CONTENT_IN_USE","Câu hỏi đang được bài học đã xuất bản sử dụng.");root.retire();return view(content.save(root),actor,false,false);}var root=lesson(id,true);editable(root,actor);governance.draftFree("lessons",id);revision(root.getRevision(),input.baseRevision());root.retire();return view(content.save(root),actor,false,false);});}
    @Transactional(isolation=Isolation.READ_COMMITTED) public Result copy(long id,Copy input,UserPrincipal actor){AssetServiceImpl.author(actor);return receipts.execute(actor,input.requestId(),"POST /api/author/questions/"+id+"/copy",input,201,()->{governance.lock();var source=version("questions",id,input.sourceVersionId(),actor);var v=content.questionVersion((Long)source.get("id")).orElseThrow(AuthoringAccess::missing);return createQuestion(v.data(),question(id,false).getOriginKey(),actor);});}
    private Unit unitView(UnitEntity unit,UserPrincipal actor){var base=unit.view();var ids=new TreeSet<Long>();for(var l:content.lessons(unit.getId())){var version=own(l,actor)&&l.getDraft()!=null?l.getDraft():l.getPublished();if(version!=null&&(own(l,actor)||l.getRetiredAt()==null))ids.addAll(version.data().objectiveIds());}return new Unit(base.id(),base.ownerId(),base.topicId(),base.title(),base.description(),base.stage(),base.sortOrder(),base.roundNumber(),base.assignedTeacherId(),base.revision(),List.copyOf(ids));}
    public Object unit(long id,UserPrincipal actor){author(actor);var unit=catalog.unit(AuthoringRequests.id(id),false).orElseThrow(AuthoringAccess::missing);editable(unit,actor);return Map.of("unit",unitView(unit,actor),"lessons",content.lessons(id).stream().map(l->view(l,actor,true,false)).toList());}
    @Transactional(isolation=Isolation.READ_COMMITTED) public Result order(long id,Order input,UserPrincipal actor){AssetServiceImpl.author(actor);return receipts.execute(actor,input.requestId(),"PUT /api/author/units/"+id+"/lesson-order",input,200,()->{governance.lock();var unit=catalog.unit(AuthoringRequests.id(id),true).orElseThrow(AuthoringAccess::missing);content.refresh(unit);editable(unit,actor);revision(unit.getRevision(),input.baseRevision());var all=content.lessons(id);if(!new HashSet<>(input.lessonIds()).equals(all.stream().map(LessonEntity::getId).collect(java.util.stream.Collectors.toSet())))throw invalid("lessonIds","Cần gửi đủ toàn bộ bài trong Unit, không trùng hoặc thiếu ID.");all.stream().map(LessonEntity::getId).sorted().forEach(v->lesson(v,true));boolean changed=false;for(int i=0;i<input.lessonIds().size();i++){var root=lesson(input.lessonIds().get(i),false);if(root.getSortOrder()!=i){root.order(i);content.save(root);changed=true;}}if(changed){unit.changed();catalog.save(unit);}return unitView(unit,actor);});}
}
